namespace{void knob(juce::Slider&s){s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,55,17);}}
ChimeraEditor::ChimeraEditor(ChimeraProcessor&p):AudioProcessorEditor(&p){title.setText("SpectralForge  |  CHIMERA AMP MATRIX  1.0",juce::dontSendNotification);title.setJustificationType(juce::Justification::centred);addAndMakeVisible(title);mode.addItemList({"CLASSIC","DUAL","MATRIX"},1);addAndMakeVisible(mode);for(auto*s:{&x1,&x2}){knob(*s);addAndMakeVisible(*s);}auto&st=p.parameters();ma=std::make_unique<CA>(st,"mode",mode);a1=std::make_unique<SA>(st,"x1",x1);a2=std::make_unique<SA>(st,"x2",x2);for(int i=0;i<3;++i){auto&l=lanes[i];auto n=juce::String(i+1);l.amp.addItemList({"Glass","Brit Edge","Tight 515","Wide Rect","Liquid Lead","Iron Tube","Solid Punch","Modern Bass"},1);addAndMakeVisible(l.amp);l.aa=std::make_unique<CA>(st,"amp"+n,l.amp);std::array<juce::Slider*,8>s{&l.drive,&l.level,&l.bass,&l.lm,&l.hm,&l.treble,&l.pres,&l.res};std::array<juce::String,8>id{"drive"+n,"level"+n,"bass"+n,"lowmid"+n,"highmid"+n,"treble"+n,"presence"+n,"resonance"+n};for(size_t k=0;k<s.size();++k){knob(*s[k]);addAndMakeVisible(*s[k]);l.sa[k]=std::make_unique<SA>(st,id[k],*s[k]);}}setSize(1180,610);}
void ChimeraEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff101217));g.setColour(juce::Colour(0xffe2e5ea));g.setFont(juce::FontOptions(24.f));g.drawText("ROUTING",25,75,100,20,juce::Justification::centredLeft);for(int i=0;i<3;++i){g.setColour(juce::Colour(0xff292d36));g.drawRoundedRectangle(20.f+i*385.f,190.f,365.f,390.f,9.f,1.2f);g.setColour(juce::Colours::white);g.drawText("LANE "+juce::String(i+1),35+i*385,202,100,22,juce::Justification::left);}}
void ChimeraEditor::resized(){title.setBounds(20,15,getWidth()-40,40);mode.setBounds(25,105,170,28);x1.setBounds(230,85,90,90);x2.setBounds(330,85,90,90);for(int i=0;i<3;++i){auto&l=lanes[i];int x=35+i*385;l.amp.setBounds(x,235,330,28);std::array<juce::Slider*,8>s{&l.drive,&l.level,&l.bass,&l.lm,&l.hm,&l.treble,&l.pres,&l.res};for(int k=0;k<8;++k)s[k]->setBounds(x+(k%4)*82,280+(k/4)*120,72,100);}}
